using System.Net.Http.Json;
using System.Text.Json;
using ModelContextProtocol.Server;

namespace McpServerDemo;

[McpServerToolType]
public sealed class WeatherTools
{
    private readonly IHttpClientFactory _httpClientFactory;

    // Constructor parameters are resolved from DI automatically.
    // The MCP SDK creates tool instances per-invocation using the
    // service provider, so any registered service can be injected here.
    public WeatherTools(IHttpClientFactory httpClientFactory)
    {
        _httpClientFactory = httpClientFactory;
    }

    [McpServerTool(Name = "get_weather")]
    [Description("Gets current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        using var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
        var current = json.GetProperty("current");

        var temp = current.GetProperty("temperature_2m").GetDouble();
        var wind = current.GetProperty("wind_speed_10m").GetDouble();

        return $"Temperature: {temp}°C, Wind: {wind} km/h";
    }

    [McpServerTool(Name = "get_location_name")]
    [Description("Geocodes a place name and returns matching coordinates.")]
    public async Task<string> GeocodeAsync(
        [Description("City or place name to search for")] string name,
        CancellationToken cancellationToken = default)
    {
        using var client = _httpClientFactory.CreateClient("WeatherApi");

        var url = $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(name)}&count=3";

        using var response = await client.GetAsync(url, cancellationToken);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);

        if (!json.TryGetProperty("results", out var results))
            return "No results found.";

        var lines = new List<string>();
        foreach (var r in results.EnumerateArray())
        {
            var city = r.GetProperty("name").GetString();
            var country = r.TryGetProperty("country", out var c) ? c.GetString() : "?";
            var lat = r.GetProperty("latitude").GetDouble();
            var lon = r.GetProperty("longitude").GetDouble();
            lines.Add($"{city}, {country} ({lat}, {lon})");
        }

        return string.Join("\n", lines);
    }
}

